_CORE_SRC = '# Action format: list[tuple[int, int, str, int]], i.e.\n# [(from_node, to_node, unit_type, count), ...].\n# Payout: equal capacities split evenly, each serving min(capacity, demand / 2).\n# Otherwise the larger capacity serves min(capacity, demand) first, and the\n# smaller serves min(capacity, demand - served_big).\n# Cost: every heavy away from its own base costs 3.0 per turn; every light\n# away from its own base costs 1.0. Moves precede payout, one edge per unit.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 70\nTYPES = ("heavy", "light")\nCAPACITY = (8, 3)\nUPKEEP = (3.0, 1.0)\n\n\ndef payout(own, opponent, demand):\n    """Exact revenue for both sides, before upkeep."""\n    if own == opponent:\n        value = min(own, demand / 2.0)\n        return value, value\n    if own > opponent:\n        first = min(own, demand)\n        return first, min(opponent, demand - first)\n    first = min(opponent, demand)\n    return min(own, demand - first), first\n\n\ndef margin(own, opponent, demand):\n    a, b = payout(own, opponent, demand)\n    return a - b\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n    hops = [[s for _ in range(n)] for s in range(n)]\n    for s in range(n):\n        for target in range(n):\n            if s != target and distances[s][target] > 0:\n                hops[s][target] = next(\n                    v for v in adjacency[s]\n                    if distances[v][target] == distances[s][target] - 1\n                )\n    return adjacency, distances, hops\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.base_demand = []\n        self.last_counter = []\n        self.last_seen = []\n        self.sticky = {}\n        self.bad_reports = 0\n\n    def _forecast(self, obs, horizon):\n        """Separate normal/surge outcomes: clipping expected demand is incorrect."""\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        demand = obs.get("demand", [None] * n)\n        counters = obs.get("surge_turns_left", [None] * n)\n        for v in range(n):\n            if demand[v] is not None and counters[v] is not None:\n                counter = int(counters[v])\n                self.base_demand[v] = (\n                    float(demand[v]) / 3.0 if counter else float(demand[v])\n                )\n                self.last_counter[v] = counter\n                self.last_seen[v] = turn\n        result = []\n        for v in range(n):\n            base = self.base_demand[v]\n            seen = self.last_seen[v]\n            probabilities = []\n            for h in range(horizon):\n                if seen < 0:\n                    probability = 1.0 - 0.9 ** 3\n                else:\n                    elapsed = turn - seen + h\n                    if elapsed < self.last_counter[v]:\n                        probability = 1.0\n                    else:\n                        probability = 1.0 - 0.9 ** min(3, elapsed)\n                probabilities.append(probability)\n            result.append((base, probabilities))\n        return result\n\n    def _source_units(self, have):\n        """Recover sticky targets using predicted positions, without assuming no skips."""\n        units = []\n        for kind in range(2):\n            for source, count in enumerate(have[kind]):\n                previous = self.sticky.get((kind, source), [])\n                for index in range(count):\n                    target = previous[index] if index < len(previous) else source\n                    units.append((kind, source, target))\n        return units\n\n    def _plan(self, obs, have, forecasts, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        opponent_home = obs["opponent_base"]\n        adjacency, distances, hops = self.map_data\n        horizon = len(forecasts[0][1])\n        weights = [0.96 ** h for h in range(horizon)]\n        prefix = [0.0]\n        for weight in weights:\n            prefix.append(prefix[-1] + weight)\n\n        enemy = [\n            8 * obs["opponent_heavy"][v] + 3 * obs["opponent_light"][v]\n            for v in range(n)\n        ]\n        units = self._source_units(have)\n        planned_capacity = [0] * n\n        want = [[0] * n for _ in range(2)]\n        cache = {}\n\n        def revenue_gain(v, capacity, extra, delay):\n            key = (v, capacity, extra, delay)\n            if key in cache:\n                return cache[key]\n            base, probabilities = forecasts[v]\n            normal = (\n                margin(capacity + extra, enemy[v], base)\n                - margin(capacity, enemy[v], base)\n            )\n            surge = (\n                margin(capacity + extra, enemy[v], round(3.0 * base, 1))\n                - margin(capacity, enemy[v], round(3.0 * base, 1))\n            )\n            value = 0.0\n            for h in range(delay, horizon):\n                p = probabilities[h]\n                value += weights[h] * (normal + p * (surge - normal))\n            cache[key] = value\n            return value\n\n        # The priority rule is discontinuous at capacity ties, not concave.\n        # Recompute priorities after each assignment rather than relying on\n        # stale concave-heap keys. Heavy units can cross many such thresholds.\n        while units:\n            if time.perf_counter() >= deadline:\n                for kind, source, old_target in units:\n                    want[kind][source] += 1\n                break\n            best = None\n            best_value = -float("inf")\n            for index, (kind, source, old_target) in enumerate(units):\n                upkeep = UPKEEP[kind]\n                return_delay = max(0, distances[source][home] - 1)\n                return_cost = upkeep * prefix[min(horizon, return_delay)]\n                for target in range(n):\n                    distance = distances[source][target]\n                    if distance < 0:\n                        continue\n                    if self.bad_reports >= 2 and distance > 1:\n                        continue\n                    if target == opponent_home:\n                        continue\n                    if target == home:\n                        value = -return_cost\n                    else:\n                        delay = max(0, distance - 1)\n                        if delay >= horizon:\n                            continue\n                        value = revenue_gain(\n                            target, planned_capacity[target], CAPACITY[kind], delay\n                        ) - upkeep * prefix[-1]\n                    # Compare to returning home, the true zero-upkeep alternative.\n                    value += return_cost\n                    # Modest hysteresis, never enough to justify a poor deployment.\n                    if target == old_target and target != home:\n                        value += 0.65\n                    if target == source and target != home:\n                        value += 0.35\n                    if value > best_value + 1e-9:\n                        best_value = value\n                        best = (index, target)\n            if best is None:\n                for kind, source, old_target in units:\n                    want[kind][source] += 1\n                break\n            index, target = best\n            kind, source, old_target = units.pop(index)\n            want[kind][target] += 1\n            planned_capacity[target] += CAPACITY[kind]\n        return want\n\n    def _legal_action(self, have, want):\n        """Closest-first surplus/deficit pairing; validate against original counts."""\n        adjacency, distances, hops = self.map_data\n        n = len(adjacency)\n        action = []\n        sticky = {}\n        for kind in range(2):\n            available = list(have[kind])\n            surplus = [max(0, have[kind][v] - want[kind][v]) for v in range(n)]\n            deficit = [max(0, want[kind][v] - have[kind][v]) for v in range(n)]\n            for v in range(n):\n                retained = min(have[kind][v], want[kind][v])\n                if retained:\n                    sticky.setdefault((kind, v), []).extend([v] * retained)\n            pairs = sorted(\n                (distances[s][t], s, t)\n                for s in range(n) if surplus[s]\n                for t in range(n) if deficit[t] and distances[s][t] > 0\n            )\n            combined = {}\n            for distance, source, target in pairs:\n                count = min(surplus[source], deficit[target], available[source])\n                if count <= 0:\n                    continue\n                hop = hops[source][target]\n                if hop not in adjacency[source] or hop == source:\n                    continue\n                surplus[source] -= count\n                deficit[target] -= count\n                available[source] -= count\n                combined[source, hop] = combined.get((source, hop), 0) + count\n                sticky.setdefault((kind, hop), []).extend([target] * count)\n            for v in range(n):\n                # Any unmatched surplus stays; it is not forgotten next turn.\n                if surplus[v]:\n                    sticky.setdefault((kind, v), []).extend([v] * surplus[v])\n            remaining = list(have[kind])\n            for (source, target), count in sorted(combined.items()):\n                count = min(count, remaining[source])\n                if count > 0 and target in adjacency[source]:\n                    action.append((int(source), int(target), TYPES[kind], int(count)))\n                    remaining[source] -= count\n        self.sticky = sticky\n        return action\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None or len(self.base_demand) != n:\n            self.map_data = preprocess_map(n, obs["edges"])\n            self.base_demand = [3.8] * n\n            self.last_counter = [0] * n\n            self.last_seen = [-1] * n\n            for base in (obs["player_base"], obs["opponent_base"]):\n                self.base_demand[base] = 0.0\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        remaining_turns = max(0, N_TURNS - int(obs["turn"]))\n        if remaining_turns == 0:\n            return []\n        horizon = min(14, remaining_turns)\n        have = [list(obs["player_heavy"]), list(obs["player_light"])]\n        forecasts = self._forecast(obs, horizon)\n        want = self._plan(obs, have, forecasts, deadline)\n        return self._legal_action(have, want)\n'
